package org.eclipse.kura.core.status.runnables;

import org.eclipse.kura.KuraException;
import org.eclipse.kura.core.status.LedManager;

public class BlinkStatusRunnable implements StatusRunnable {

    private final LedManager ledManager;

    private final int onTimeMillis;
    private final int offTimeMillis;

    private boolean enabled;

    public BlinkStatusRunnable(LedManager ledManager, int onTimeMillis, int offTimeMillis) {
        this.ledManager = ledManager;
        this.onTimeMillis = onTimeMillis;
        this.offTimeMillis = offTimeMillis;
        this.enabled = true;
    }

    @Override
    public void run() {
        while (this.enabled) {
            try {
                this.ledManager.writeLed(true);
                Thread.sleep(this.onTimeMillis);
                this.ledManager.writeLed(false);
                Thread.sleep(this.offTimeMillis);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                this.enabled = false;
            } catch (KuraException e) {
                this.enabled = false;
            }
        }
    }

    @Override
    public void stopRunnable() {
        this.enabled = false;
    }
}
